import numpy as np
from scipy.ndimage import distance_transform_edt,label,gaussian_filter1d
from PIL import Image,ImageDraw

def contours(field,level):
    # Marching squares, edges indexed by their shared lattice endpoints.
    h,w=field.shape; inside=field>level
    cells=np.argwhere((inside[:-1,:-1]!=inside[1:,:-1])|(inside[:-1,:-1]!=inside[:-1,1:])|(inside[:-1,:-1]!=inside[1:,1:]))
    adj={};coords={}
    for y,x in cells:
        corners=[(y,x),(y,x+1),(y+1,x+1),(y+1,x)]
        cross=[]
        for a,b in zip(corners,corners[1:]+corners[:1]):
            fa,fb=field[a],field[b]
            if (fa>level)==(fb>level):continue
            key=tuple(sorted((a,b)))
            t=(level-fa)/(fb-fa);coords[key]=np.array(a)+(np.array(b)-a)*t;cross.append(key)
        for i in range(0,len(cross),2):
            a,b=cross[i:i+2];adj.setdefault(a,[]).append(b);adj.setdefault(b,[]).append(a)
    loops=[]
    while adj:
        start=next(iter(adj));p=start;last=None;pts=[]
        while p in adj:
            pts.append(coords[p]);ns=adj.pop(p);n=next((n for n in ns if n!=last),start);last,p=p,n
            if p==start:break
        if len(pts)>5:
            a=np.array(pts);a=gaussian_filter1d(a,1.3,axis=0,mode='wrap');a=np.vstack([a,a[0]]);loops.append(a)
    return loops

def build(mask,first=2.8,spacing=3.2):
    d=distance_transform_edt(mask)
    loops=[]
    for lev in np.arange(first,d.max(),spacing):
        for c in contours(d,lev):loops.append((lev,c))
    return d,loops

if __name__=='__main__':
    m=np.array(Image.open('/app/target.png'))[:,:,0]<100;l,n=label(m)
    im=Image.open('/app/target.png').convert('RGB');dr=ImageDraw.Draw(im)
    for i in range(1,n+1):
        d,loops=build(l==i)
        print(i,'loops',len(loops),'length mm',sum(np.linalg.norm(np.diff(c,axis=0),axis=1).sum() for _,c in loops)*.22186)
        for lev,c in loops:dr.line([(float(x),float(y)) for y,x in c],fill=(230,50,60),width=1)
    im.save('/app/output/planned.png')
